        }
    }

    /// The engine's name for a rung the script engine reports: the two modules each declare the
    /// five readings, since the script engine does not depend on the runtime.
    private static func payloadReading(of reading: SceLua.PayloadReading) -> SceRuntime.PayloadReading {
        switch reading {
        case .absent: return .absent
        case .dom: return .dom
        case .structured: return .structured
        case .text: return .text
        case .undecodable: return .undecodable
        }
    }

    /// W3C SCXML 5.9.1: a `cond` that cannot be evaluated is false, and raises `error.execution`.
    private func evaluateGuard(_ condition: String, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) -> Bool {
        var failed = false
        return evaluateCond(condition, of: "<transition>", failed: &failed, engine: engine)
    }

    /// W3C SCXML 4.3, 5.9.1: the same for the `cond` of an `<if>` or `<elseif>`, which also says that
    /// it failed, because the element that held it ends its block once the chain has run (§scxml-4.9).
    private func evaluateIfCond(_ condition: String, failed: inout Bool, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) -> Bool {
        evaluateCond(condition, of: "<if>", failed: &failed, engine: engine)
    }

    private func evaluateCond(
        _ condition: String,
        of element: String,
        failed: inout Bool,
        engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>
    ) -> Bool {
        do {
            return try ensureLua().evaluateCondition(condition, chunkName: "=cond")
        } catch {
            raiseExecutionError("a \(element) cond failed to evaluate", engine: engine)
            failed = true
            return false
        }
    }


    // ------------------------------------------------------------------
    // Child sessions (W3C SCXML 6.4)
    // ------------------------------------------------------------------

    /// W3C SCXML 6.4: the `<invoke>`s a state's entry deferred to the end of the
    /// macrostep. A state exited before then drops its own.
    private var pendingInvokes: [PendingInvoke<EmptyFinalizeUpdatesTheLocationState>] = []

    /// W3C SCXML 6.4.1: the invocations running, by the id their `<invoke>` carries.
    private var activeInvokes: [String: ChildSession] = [:]

    /// The session `<invoke>` `inv_absent` started, while its state is active.
    private var sceInvokeChildInvAbsent: InvokedSession<EmptyFinalizeUpdatesTheLocationSceSynthInvokeInvAbsentPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneInvAbsent = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsInvAbsent = 0

    /// The session `<invoke>` `inv_empty` started, while its state is active.
    private var sceInvokeChildInvEmpty: InvokedSession<EmptyFinalizeUpdatesTheLocationSceSynthInvokeInvEmptyPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneInvEmpty = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsInvEmpty = 0

    /// The session `<invoke>` `inv_unmatched` started, while its state is active.
    private var sceInvokeChildInvUnmatched: InvokedSession<EmptyFinalizeUpdatesTheLocationSceSynthInvokeInvUnmatchedPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneInvUnmatched = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsInvUnmatched = 0

    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("inv_absent".utf8) {
                sceStartInvokeInvAbsent(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("inv_empty".utf8) {
                sceStartInvokeInvEmpty(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("inv_unmatched".utf8) {
                sceStartInvokeInvUnmatched(pending, engine: engine)
                return
            }
        }
    }

    /// Starts the session of `<invoke>` `inv_absent` (W3C SCXML 6.4).
    private func sceStartInvokeInvAbsent(_ pending: PendingInvoke<EmptyFinalizeUpdatesTheLocationState>, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        // W3C SCXML C.1: the child is known by the id its parent mints for it and
        // keys the invocation on, so the sender of what it sends is the id it
        // publishes in `_ioprocessors`.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let childPolicy = EmptyFinalizeUpdatesTheLocationSceSynthInvokeInvAbsentPolicy()
        // W3C SCXML 6.4.1: the child is handed the values this invoke names before it
        // initializes.
        var seeds: [String: LuaSeed] = [:]
        if let seedValue = evaluateSeed("guard") {
            seeds["guard"] = seedValue
        } else {
            raiseExecutionError("<invoke> namelist entry 'guard' could not be read", engine: engine)
        }
        childPolicy.acceptSeeds(seeds)

        let session = InvokedSession(
            policy: childPolicy,
            sessionID: childSessionID,
            queue: ParentEventQueue(parentSessionID: sessionID)
        )
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["inv_absent"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "inv_absent",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        // W3C SCXML 6.4: the child's delayed sends are measured on this machine's
        // clock, so a delay on either side of the boundary is the same instant and a
        // clock its host advances moves the child too.
        session.engine.setClock(engine.clock())
        // SCE_MESH.md §21.3: the child's router is the one the factory answers for this invoke
        // and this document (empty for a child written in line), installed before the child
        // initializes, since its first state may already send.
        engine.startChildMesh(of: session, invokeID: "inv_absent", document: documentStem("#empty_finalize_updates_the_location__sce_synth_invoke__inv_absent"))
        session.initialize()
        sceInvokeChildInvAbsent = session
        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeInvAbsent(engine: engine)
    }

    /// Takes what the session of `<invoke>` `inv_absent` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeInvAbsent(engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        guard let child = sceInvokeChildInvAbsent, !sceInvokeDoneInvAbsent else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "inv_absent",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneInvAbsent = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "inv_absent", donedata: child.donedataAtFinal, engine: engine)
        }
    }

