    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        if !sceInvokeDoneInvAbsent, let child = sceInvokeChildInvAbsent {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "inv_absent",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeInvAbsent(engine: engine)
        }
        if !sceInvokeDoneInvEmpty, let child = sceInvokeChildInvEmpty {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "inv_empty",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeInvEmpty(engine: engine)
        }
        if !sceInvokeDoneInvUnmatched, let child = sceInvokeChildInvUnmatched {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "inv_unmatched",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeInvUnmatched(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        sceSettleInvokeInvAbsent(engine: engine)
        sceSettleInvokeInvEmpty(engine: engine)
        sceSettleInvokeInvUnmatched(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneInvAbsent, let due = sceInvokeChildInvAbsent?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneInvEmpty, let due = sceInvokeChildInvEmpty?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneInvUnmatched, let due = sceInvokeChildInvUnmatched?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// W3C SCXML 6.5: the `<finalize>` of the invocation an event came from runs before the
    /// parent selects transitions on that event, in the parent's data model, with `_event` the
    /// event the child sent. The invocation is the one whose session the event names as its
    /// sender (docs/adr/0090: the session id travels beside the origin, and nothing reads the
    /// origin's address to find a session); an event from anywhere else (the host, this
    /// machine itself) finalizes nothing.
    public func executeFinalizeForChildEvent(_ event: inout EventWithMetadata<EmptyFinalizeUpdatesTheLocationEvent>, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>) {
        guard let sender = event.metadata.sender, !sender.isEmpty,
            let child = activeInvokes.values.first(where: { $0.sessionID == sender && !$0.finalizeScript.isEmpty })
        else {
            return
        }
        populateEventMetadata(event.metadata)
        bindCurrentEvent(event.event, engine: engine)
        if !executeScript(child.finalizeScript, name: "=finalize") {
            raiseExecutionError("<finalize> failed to execute", engine: engine)
        }
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("inv_absent".utf8) {
            if let child = sceInvokeChildInvAbsent, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("inv_empty".utf8) {
            if let child = sceInvokeChildInvEmpty, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("inv_unmatched".utf8) {
            if let child = sceInvokeChildInvUnmatched, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("inv_absent".utf8) {
            return sceInvokeChildInvAbsent.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("inv_empty".utf8) {
            return sceInvokeChildInvEmpty.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("inv_unmatched".utf8) {
            return sceInvokeChildInvUnmatched.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["inv_absent"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildInvAbsent.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["inv_empty"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildInvEmpty.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["inv_unmatched"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildInvUnmatched.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["inv_absent"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildInvAbsent {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        if let session = activeInvokes["inv_empty"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildInvEmpty {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        if let session = activeInvokes["inv_unmatched"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildInvUnmatched {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: EmptyFinalizeUpdatesTheLocationState, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .absentPhase:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {

                // W3C SCXML 6.2: send id="__send_1"
                do {
                    let sendEventData = ""
                    do {
                    // W3C SCXML 6.2 / C.1: deliver the event to this session's own external
                    // queue, carrying the pair the SCXML processor writes for this session as
                    // its origin and this session as its sender (docs/adr/0090).
                        // W3C SCXML 6.2: delayed to this session's external queue.
                        engine.scheduleEvent(
                            EmptyFinalizeUpdatesTheLocationEvent.timeoutAbsent,
                            delay: Duration.milliseconds(3000),
                            sendID: "__send_1",
                            eventData: sendEventData,
                            sender: self.sessionID
                        )
                    }
                }
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsInvAbsent += 1
                let generatedInvokeID = "absentPhase.\(sceInvokeStartsInvAbsent).inv_absent"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .absentPhase,
                    documentID: "inv_absent"
                ))
            }
        case .emptyPhase:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {

                // W3C SCXML 6.2: send id="__send_0"
                do {
                    let sendEventData = ""
                    do {
                    // W3C SCXML 6.2 / C.1: deliver the event to this session's own external
                    // queue, carrying the pair the SCXML processor writes for this session as
                    // its origin and this session as its sender (docs/adr/0090).
                        // W3C SCXML 6.2: delayed to this session's external queue.
                        engine.scheduleEvent(
                            EmptyFinalizeUpdatesTheLocationEvent.timeoutEmpty,
                            delay: Duration.milliseconds(3000),
                            sendID: "__send_0",
                            eventData: sendEventData,
                            sender: self.sessionID
                        )
                    }
                }
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsInvEmpty += 1
                let generatedInvokeID = "emptyPhase.\(sceInvokeStartsInvEmpty).inv_empty"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .emptyPhase,
                    documentID: "inv_empty"
                ))
            }
        case .unmatchedPhase:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {

                // W3C SCXML 6.2: send id="__send_2"
                do {
                    let sendEventData = ""
                    do {
                    // W3C SCXML 6.2 / C.1: deliver the event to this session's own external
                    // queue, carrying the pair the SCXML processor writes for this session as
                    // its origin and this session as its sender (docs/adr/0090).
                        // W3C SCXML 6.2: delayed to this session's external queue.
                        engine.scheduleEvent(
                            EmptyFinalizeUpdatesTheLocationEvent.timeoutUnmatched,
                            delay: Duration.milliseconds(3000),
                            sendID: "__send_2",
                            eventData: sendEventData,
                            sender: self.sessionID
                        )
                    }
                }
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsInvUnmatched += 1
                let generatedInvokeID = "unmatchedPhase.\(sceInvokeStartsInvUnmatched).inv_unmatched"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .unmatchedPhase,
                    documentID: "inv_unmatched"
                ))
            }
        default:
