    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: EmptyFinalizeUpdatesTheLocationState, engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>, configurationBeforeExit: [EmptyFinalizeUpdatesTheLocationState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .absentPhase:
            cancelInvokesForState(&pendingInvokes, .absentPhase)
            sceInvokeChildInvAbsent?.stop()
            sceInvokeChildInvAbsent?.detachMesh()
            sceInvokeChildInvAbsent = nil
            activeInvokes["inv_absent"] = nil
            sceInvokeDoneInvAbsent = false
        case .emptyPhase:
            cancelInvokesForState(&pendingInvokes, .emptyPhase)
            sceInvokeChildInvEmpty?.stop()
            sceInvokeChildInvEmpty?.detachMesh()
            sceInvokeChildInvEmpty = nil
            activeInvokes["inv_empty"] = nil
            sceInvokeDoneInvEmpty = false
        case .unmatchedPhase:
            cancelInvokesForState(&pendingInvokes, .unmatchedPhase)
            sceInvokeChildInvUnmatched?.stop()
            sceInvokeChildInvUnmatched?.detachMesh()
            sceInvokeChildInvUnmatched = nil
            activeInvokes["inv_unmatched"] = nil
            sceInvokeDoneInvUnmatched = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: EmptyFinalizeUpdatesTheLocationState,
        event: EmptyFinalizeUpdatesTheLocationEvent,
        engine: Engine<EmptyFinalizeUpdatesTheLocationPolicy>
    ) -> EnabledTransition<EmptyFinalizeUpdatesTheLocationState>? {
