                }
            }
            if event == .fromAbsentChild {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.unmatchedPhase)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .timeoutAbsent {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failAbsentChildSilent)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        case .emptyPhase:
            if event == .fromEmptyChild {
                // W3C SCXML 5.9: cond="tally === 7" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(tally == 7)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.absentPhase)],
                        transitionIndex: 0,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .fromEmptyChild {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failNotUpdated)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .timeoutEmpty {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failEmptyChildSilent)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        case .unmatchedPhase:
            if event == .fromUnmatchedChild {
                // W3C SCXML 5.9: cond="keeper !== 3" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(keeper ~= 3)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failUnmatchedNameWrote)],
                        transitionIndex: 0,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .fromUnmatchedChild {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.pass)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .timeoutUnmatched {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.failUnmatchedChildSilent)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

